var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// {orderId} in the route, id in the handler: id is read from ?id=
app.MapGet("/orders/{orderId:int}", (int id) => $"Order {id}");

// headers are never inferred: apiKey is read from ?apiKey=
app.MapGet("/reports", (string apiKey) => "report");

// a record isn't read from the query string: it's inferred as the body
app.MapGet("/orders", (OrderQuery query) => query);
app.Run();

public record OrderQuery(string? Status, int Page = 1);

using Microsoft.AspNetCore.Mvc;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

app.MapGet("/orders/{orderId:int}", (int orderId) => $"Order {orderId}");

app.MapGet("/reports",
    ([FromHeader(Name = "X-Api-Key")] string apiKey) => "report");

// each property binds by the usual rules: Status and Page from the query
app.MapGet("/orders", ([AsParameters] OrderQuery query) => query);
app.Run();

public record OrderQuery(string? Status, int Page = 1);
